#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int iNumber = 10;

    iNumber += 5;
    cout << iNumber << endl;

    cout << ++iNumber << endl;
    cout << iNumber++ << endl;
    cout << iNumber << endl;

    iNumber <<= 2;
    cout << iNumber << endl;

    cout << (iNumber % 2 == 0) << endl;

    return 0;
}
